 "content": "def transform(grid):
    """Expand a centered marker into diagonal, period-four bands."""
    width = len(grid[0])
    center = next(c for c, value in enumerate(grid[0]) if value != 0)
    out = [[0] * width for _ in range(width)]
    for r in range(width):
        for c in range(width):
            if c == center - r or c == center + r:
                out[r][c] = 2
            elif abs(c - center) <= r and (c - r - center) % 4 == 0:
                out[r][c] = 1
    return out
